const { TestEnvironment } = require('jest-environment-node')
const fs = require('node:fs')
const path = require('node:path')

// One JSON line per jest-circus event, to `<test file>.events.jsonl`: the event's keys, then what a
// handler reads of the event, the objects it names and the state, by value where the value is
// plain and by shape where it is not (functions, processes, regular expressions, errors).
const SYNC = new Set([
  'start_describe_definition',
  'finish_describe_definition',
  'add_hook',
  'add_test',
  'error',
  'error_handled',
])
const isError = (value) => value !== null && typeof value === 'object' && 'message' in value
const errorShape = (value) =>
  Array.isArray(value) ? value.map(errorShape) : isError(value) ? { message: String(value.message) } : { value: typeof value }
const nameOf = (block) => (block ? block.name : null)
const keys = (value) => Object.keys(value).sort()

function test(entry) {
  return {
    keys: keys(entry),
    name: entry.name,
    parent: nameOf(entry.parent),
    mode: entry.mode === undefined ? '<undefined>' : entry.mode,
    status: entry.status,
    invocations: entry.invocations,
    errors: entry.errors.map(errorShape),
    retryReasons: entry.retryReasons.map(errorShape),
    concurrent: entry.concurrent,
    failing: entry.failing,
    fn: typeof entry.fn,
    asyncError: errorShape(entry.asyncError),
    timeout: String(entry.timeout),
    seenDone: entry.seenDone,
    numPassingAsserts: entry.numPassingAsserts,
    startedAt: typeof entry.startedAt,
    duration: typeof entry.duration,
  }
}

function block(entry) {
  return {
    keys: keys(entry),
    name: entry.name,
    parent: nameOf(entry.parent),
    mode: entry.mode === undefined ? '<undefined>' : entry.mode,
    children: entry.children.map((child) => `${child.type}:${child.name}`),
    hooks: entry.hooks.map((hook) => hook.type),
    tests: entry.tests.map((child) => child.name),
  }
}

function hook(entry) {
  return {
    keys: keys(entry),
    type: entry.type,
    parent: nameOf(entry.parent),
    fn: typeof entry.fn,
    asyncError: errorShape(entry.asyncError),
    timeout: String(entry.timeout),
    seenDone: entry.seenDone,
  }
}

function state(value) {
  return {
    keys: keys(value),
    currentDescribeBlock: nameOf(value.currentDescribeBlock),
    currentlyRunningTest: value.currentlyRunningTest ? value.currentlyRunningTest.name : null,
    expand: String(value.expand),
    hasFocusedTests: value.hasFocusedTests,
    hasStarted: value.hasStarted,
    includeTestLocationInResult: value.includeTestLocationInResult,
    maxConcurrency: value.maxConcurrency,
    originalGlobalErrorHandlers: value.originalGlobalErrorHandlers ? keys(value.originalGlobalErrorHandlers) : null,
    parentProcess: value.parentProcess === process,
    processErrorGeneration: value.processErrorGeneration,
    randomize: String(value.randomize),
    rootDescribeBlock: block(value.rootDescribeBlock),
    // A seed the run was given is logged; Jest's own default is random.
    seed: value.seed === 42 ? 42 : typeof value.seed,
    testNamePattern: value.testNamePattern ? String(value.testNamePattern) : null,
    testTimeout: value.testTimeout,
    unhandledErrors: value.unhandledErrors.map(errorShape),
  }
}

function summarize(event, current) {
  const out = { name: event.name, keys: keys(event) }
  for (const key of ['blockName', 'testName', 'hookType', 'concurrent', 'failing']) {
    if (key in event) out[key] = event[key]
  }
  if ('mode' in event) out.mode = event.mode === undefined ? '<undefined>' : event.mode
  if ('timeout' in event) out.timeout = String(event.timeout)
  if ('fn' in event) out.fn = typeof event.fn
  if ('asyncError' in event) out.asyncError = errorShape(event.asyncError)
  if ('testNamePattern' in event) out.testNamePattern = String(event.testNamePattern)
  if ('parentProcess' in event) out.parentProcess = event.parentProcess === process
  if ('runtimeGlobals' in event) out.runtimeGlobals = typeof event.runtimeGlobals
  if ('error' in event) out.error = errorShape(event.error)
  if (event.test) out.test = test(event.test)
  if ('describeBlock' in event) out.describeBlock = event.describeBlock ? block(event.describeBlock) : null
  if (event.hook) out.hook = hook(event.hook)
  if (event.tests) out.tests = event.tests.map((entry) => entry.name)
  out.state = state(current)
  return out
}

/** Whether `plan` (what a test file asked for with `__throwAt`) names this event. */
function matches(plan, event) {
  if (plan.event !== event.name) return false
  if (plan.test !== undefined && (!event.test || event.test.name !== plan.test)) return false
  if (plan.block !== undefined && (!event.describeBlock || event.describeBlock.name !== plan.block)) return false
  return true
}

class RecordingEnvironment extends TestEnvironment {
  constructor(config, context) {
    super(config, context)
    this.eventsFile = path.join(
      config.projectConfig.rootDir,
      `${path.basename(context.testPath).replace(/\.test\.ts$/, '')}.events.jsonl`,
    )
    this.plan = undefined
    const options = config.projectConfig.testEnvironmentOptions || {}
    this.async = options.async === true
    this.global.__log = (marker) => this.record({ marker })
    // A test file asks the handler to throw once, at one event.
    this.global.__throwAt = (plan) => {
      this.plan = plan
      this.matched = 0
    }
  }

  record(entry) {
    fs.appendFileSync(this.eventsFile, JSON.stringify(entry) + '\n')
  }

  handleTestEvent(event, current) {
    // `testEnvironmentOptions.async`: a 3 ms wait at every run event, which the runner awaits.
    if (this.async && !SYNC.has(event.name)) return this.handleAsync(event, current)
    this.record(summarize(event, current))
    this.throwIfAsked(event)
  }

  async handleAsync(event, current) {
    this.record({ ...summarize(event, current), phase: 'begin' })
    await new Promise((resolve) => setTimeout(resolve, 3))
    this.record({ name: event.name, phase: 'end' })
    this.throwIfAsked(event)
  }

  throwIfAsked(event) {
    if (this.plan !== undefined && matches(this.plan, event)) {
      // `nth`: the how-many-th matching event (the adapter's own root `beforeEach` comes first).
      this.matched += 1
      if (this.matched < (this.plan.nth || 1)) return
      this.plan = undefined
      this.record({ threw: event.name })
      throw new Error(`handler boom at ${event.name}`)
    }
  }
}

module.exports = RecordingEnvironment
